def cart(p,R,grip=None,n=50):
    start=eef(); q=qnow(); g=proprio()[36] if grip is None else grip
    from scipy.spatial.transform import Slerp
    slerp=Slerp([0,1],Rotation.from_matrix(np.stack([forward(q)[1],R])))
    arr=[]
    for a in np.linspace(0,1,n):
        a=a*a*(3-2*a)
        pt=start*(1-a)+np.asarray(p)*a; rt=slerp(a).as_matrix(); seed=q.copy()
        def err(qj):
            ep,er=forward(qj)
            return np.r_[(ep-pt)*8, Rotation.from_matrix(rt@er.T).as_rotvec(),(qj-seed)*.008]
        sol=least_squares(err,seed,bounds=([-2.89,-1.76,-2.89,-3.07,-2.89,-.01,-2.89],[2.89,1.76,2.89,-.07,2.89,3.75,2.89]),max_nfev=60)
